/* =============================================================
   VirtaViral — assets.js
   All images embedded as data URIs.
   No folder structure needed — upload this file alongside the HTML files.
   ============================================================= */

(function () {
  var LOGO_PRIMARY = "data:image/png;base64,";
  var LOGO_STACKED = "data:image/png;base64,";
  var FAVICON      = "data:image/png;base64,";
  var APPLE_ICON   = "data:image/png;base64,";
  var OG_IMAGE     = "data:image/jpeg;base64,";

  function inject() {
    // Logos — targeted by data-logo attribute
    document.querySelectorAll('[data-logo="primary"]').forEach(function(el) {
      el.src = LOGO_PRIMARY;
    });
    document.querySelectorAll('[data-logo="stacked"]').forEach(function(el) {
      el.src = LOGO_STACKED;
    });

    // Favicon
    var fav = document.querySelector('link[rel="icon"]');
    if (fav) fav.href = FAVICON;

    // Apple touch icon
    var apple = document.querySelector('link[rel="apple-touch-icon"]');
    if (apple) apple.href = APPLE_ICON;

    // OG image
    var og = document.querySelector('meta[property="og:image"]');
    if (og) og.setAttribute('content', OG_IMAGE);
  }

  // Run immediately (script is deferred to end of body)
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', inject);
  } else {
    inject();
  }
})();
